test_suite:
test('generates inclusive range', () => {
  expect(range(1, 5)).toEqual([1, 2, 3, 4, 5]);
});

test('respects step parameter', () => {
  expect(range(0, 10, 2)).toEqual([0, 2, 4, 6, 8, 10]);
});

test('returns empty array when start > end', () => {
  expect(range(5, 3)).toEqual([]);
});

test('handles same start and end', () => {
  expect(range(3, 3)).toEqual([3]);
});

// __hidden__
test('step larger than range produces single element', () => {
  expect(range(1, 4, 10)).toEqual([1]);
});

solution:
export function range(start, end, step = 1) {
  const result = [];
  for (let i = start; i <= end; i += step) {
    result.push(i);
  }
  return result;
}
